#!/usr/bin/env python3
"""PreToolUse hook for Bash. Blocks `gh pr create` to the base branch when the branch touched a path in the docs map and carries no docs decision.

A decision is either a change to a Claude artifact on the branch, or a commit whose message carries a `Claude-Docs:` trailer.
`/claude-docs-check` produces both. PRs to other bases (promotions) are not checked.
"""
import fnmatch
import json
import os
import re
import shlex
import subprocess
import sys

# --- config ---------------------------------------------------------------
MAP = ".claude/skills/claude-docs-check/map.json"  # carries the base branch and the triggers
DEFAULT_BASE = "main"  # used only when map.json has no "base"
# --------------------------------------------------------------------------


def deny(reason: str) -> None:
    print(json.dumps({"hookSpecificOutput": {"hookEventName": "PreToolUse", "permissionDecision": "deny", "permissionDecisionReason": reason}}))
    sys.exit(0)


def git(root: str, *args: str) -> str:
    try:
        return subprocess.run(["git", "-C", root, *args], capture_output=True, text=True, timeout=15).stdout
    except (FileNotFoundError, subprocess.TimeoutExpired):
        return ""


def base_of(command: str, default: str) -> str:
    try:
        tokens = shlex.split(command, posix=True)
    except ValueError:
        return default
    for i, tok in enumerate(tokens):
        if tok in ("--base", "-B") and i + 1 < len(tokens):
            return tokens[i + 1]
        if tok.startswith("--base="):
            return tok[len("--base="):]
    return default


def main() -> None:
    try:
        payload = json.loads(sys.stdin.read())
    except json.JSONDecodeError:
        sys.exit(0)
    command = ((payload.get("tool_input") or {}).get("command") or "").strip()
    if not re.search(r"\bgh\s+pr\s+create\b", command):
        sys.exit(0)
    root = payload.get("cwd") or os.getcwd()
    try:
        spec = json.load(open(os.path.join(root, MAP)))
    except (OSError, json.JSONDecodeError):
        sys.exit(0)
    base = base_of(command, spec.get("base", DEFAULT_BASE))
    if base != spec.get("base", DEFAULT_BASE):
        sys.exit(0)
    ref = f"origin/{base}" if git(root, "rev-parse", "--verify", "-q", f"origin/{base}").strip() else base
    changed = [f for f in git(root, "diff", "--name-only", f"{ref}...HEAD").splitlines() if f]
    if not changed:
        sys.exit(0)
    hits = [(f, t["artifacts"]) for t in spec["triggers"] for f in changed if any(fnmatch.fnmatch(f, g) for g in t["paths"])]
    if not hits:
        sys.exit(0)
    prefixes = tuple(spec.get("artifact_prefixes", []))
    if any(f.startswith(prefixes) for f in changed):
        sys.exit(0)
    if re.search(r"^Claude-Docs: ", git(root, "log", "--format=%B", f"{ref}..HEAD"), re.M):
        sys.exit(0)
    lines = "\n".join(f"  {f} -> {', '.join(a)}" for f, a in hits[:12])
    deny(
        "This branch touched paths the Claude Code instructions describe, and carries no docs decision:\n"
        f"{lines}\n"
        "Run /claude-docs-check first. It updates the mapped files on Opus, or records why nothing changes, as a `Claude-Docs:` commit trailer."
    )


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""PreToolUse hook for Bash. Blocks `gh pr create` / `gh pr edit --title` when the title is not Conventional Commits.

Format: type(scope): subject. Scope is optional and free-form. Subject starts lowercase and has no trailing period.
The CI check (if any) stays the real gate; this hook saves a round trip.
"""
import json
import re
import shlex
import sys

# --- config ---------------------------------------------------------------
ALLOWED_TYPES = ("feat", "fix", "chore", "docs", "refactor", "perf", "test", "ci", "build", "revert", "release")
# --------------------------------------------------------------------------
SUBJECT_RE = re.compile(r"^[a-z].+[^.]$")
TITLE_RE = re.compile(r"^(?P<type>[a-z]+)(?:\((?P<scope>[a-z0-9][a-z0-9-]*)\))?:\s+(?P<subject>.+)$")
GH_PR_RE = re.compile(r"\bgh\s+pr\s+(?:create|edit)\b")


def deny(reason: str) -> None:
    print(json.dumps({"hookSpecificOutput": {"hookEventName": "PreToolUse", "permissionDecision": "deny", "permissionDecisionReason": reason}}))
    sys.exit(0)


def extract_title(command: str) -> str | None:
    try:
        tokens = shlex.split(command, posix=True)
    except ValueError:
        return None
    for i, tok in enumerate(tokens):
        if tok in ("--title", "-t") and i + 1 < len(tokens):
            return tokens[i + 1]
        if tok.startswith("--title="):
            return tok[len("--title="):]
    return None


def validate(title: str) -> str | None:
    m = TITLE_RE.match(title)
    if not m:
        return f"Expected `type(scope): subject`, got {title!r}. Scope is optional; the space after the colon is not."
    if m.group("type") not in ALLOWED_TYPES:
        return f"Type {m.group('type')!r} is not one of: {', '.join(ALLOWED_TYPES)}."
    subject = m.group("subject")
    if not SUBJECT_RE.match(subject):
        if subject.endswith("."):
            return "Subject must not end with a period."
        return "Subject must start with a lowercase letter. If it starts with a name, put a verb first: `add`, `wire`, `port`."
    return None


def main() -> None:
    try:
        payload = json.loads(sys.stdin.read())
    except json.JSONDecodeError:
        sys.exit(0)
    command = ((payload.get("tool_input") or {}).get("command") or "").strip()
    if not command or not GH_PR_RE.search(command):
        sys.exit(0)
    title = extract_title(command)
    if title is None:
        sys.exit(0)
    err = validate(title)
    if err:
        deny(f"PR title blocked before `gh` ran: {err} Fix the --title value and run it again.")
    sys.exit(0)


if __name__ == "__main__":
    main()

