    """True for `git [global opts] commit ...`."""
    return bool(re.match(r"^\s*git\s+(?:--?[A-Za-z][A-Za-z0-9=._/-]*\s+)*commit\b", part))


def is_git_push(part: str) -> bool:
    """True for `git push ...`."""
    return bool(re.match(r"^\s*git\s+push\b", part))


