    """True when a commit or push skips git hooks. `-n` means --no-verify on commit but dry-run on push."""
    if re.match(r"^\s*git\s+commit\b", part):
        return bool(re.search(r"(?:^|\s)(?:--no-verify|-n)(?:\s|$)", part))
    if is_git_push(part):
