"""Scratch pytest plugin: time every garbage-collector pass and report the slow ones at the end."""

import gc
import time

_started: dict[int, float] = {}
_passes: list[tuple[float, int]] = []


def _track(phase: str, info: dict[str, int]) -> None:
    if phase == "start":
        _started[info["generation"]] = time.perf_counter()
    else:
        _passes.append((time.perf_counter() - _started.pop(info["generation"]), info["generation"]))


def pytest_configure() -> None:
    gc.callbacks.append(_track)


def pytest_unconfigure() -> None:
    slow = sorted(_passes, reverse=True)
    over_5ms = [p for p in slow if p[0] > 0.005]
    print(f"\ngc passes: {len(_passes)}, over 5 ms: {len(over_5ms)}, slowest: "
          + ", ".join(f"gen{g} {d * 1000:.1f}ms" for d, g in slow[:6]))

