1	# Replaces the image's main config. Serves the built SPA and proxies /api/ to the API replicas.
2	# Directive reference: https://nginx.org/en/docs/dirindex.html
3	
4	# Pinned, because "auto" starts one worker per CPU and each worker keeps its own idle upstream connections.
5	worker_processes 2;
6	# The unprivileged image can write only to /tmp.
7	pid /tmp/nginx.pid;
8	error_log /dev/stderr warn;
9	
10	# Each proxied request holds two connections: one to the browser, one to the API.
11	events {
12	    worker_connections 4096;
13	}
14	
15	http {
16	    include mime.types;
17	    access_log /dev/stdout;
18	
19	    client_body_temp_path /tmp/client_temp;
20	    proxy_temp_path /tmp/proxy_temp;
21	    fastcgi_temp_path /tmp/fastcgi_temp;
22	    uwsgi_temp_path /tmp/uwsgi_temp;
23	    scgi_temp_path /tmp/scgi_temp;
24	
25	    gzip on;
26	    gzip_types text/css application/javascript text/javascript application/json;
27	
28	    # Docker's embedded DNS. A short validity picks up replicas whose addresses change.
29	    resolver 127.0.0.11 valid=10s ipv6=off;
30	
31	    # Pass on the caller's request id, or make one, so nginx and the API log the same id.
32	    map $http_x_request_id $req_id {
33	        default $http_x_request_id;
34	        "" $request_id;
35	    }
36	
37	    upstream api {
38	        # "resolve" re-reads the replicas' addresses from DNS; it needs a shared zone.
39	        # https://nginx.org/en/docs/http/ngx_http_upstream_module.html#resolve
40	        zone api 64k;
41	        server api:8000 resolve;
42	        # At most 16 idle connections per worker, 32 in all, well under each replica's 200-connection limit.
43	        # Without "local", the /api/ and /api/docs locations share one cache.
44	        # https://nginx.org/en/docs/http/ngx_http_upstream_module.html#keepalive
45	        keepalive 16;
46	        # Shorter than uvicorn's 75 s, so nginx never reuses a connection the API is closing.
47	        keepalive_timeout 60s;
48	    }
49	
50	    server {
51	        listen 8080;
52	        server_tokens off;
53	        client_max_body_size 64k;
54	        root /usr/share/nginx/html;
55	
56	        # A location with its own add_header drops these, so each such location repeats them.
57	        # https://nginx.org/en/docs/http/ngx_http_headers_module.html#add_header
58	        set $csp "default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; font-src 'self'; connect-src 'self'; object-src 'none'; base-uri 'self'; form-action 'self'; frame-ancestors 'none'";
59	        add_header Content-Security-Policy $csp always;
60	        add_header X-Content-Type-Options nosniff always;
61	        add_header Referrer-Policy strict-origin-when-cross-origin always;
62	        add_header X-Frame-Options DENY always;
63	        add_header Permissions-Policy "camera=(), microphone=(), geolocation=()" always;
64	        add_header Cross-Origin-Opener-Policy same-origin always;
65	
66	        # The health probes are for Docker and Kubernetes only, never the public front door.
67	        location = /livez {
68	            return 404;
69	        }
70	        location = /readyz {
71	            return 404;
72	        }
73	
74	        # Since nginx 1.29.7 the proxy speaks HTTP/1.1 and sends no Connection header by default,
75	        # which upstream keep-alive needs. https://nginx.org/en/CHANGES-1.30
76	        location /api/ {
77	            proxy_pass http://api;
78	            proxy_set_header Host $host;
79	            proxy_set_header X-Request-ID $req_id;
80	            proxy_read_timeout 30s;
81	        }
82	
83	        # Swagger UI loads its script and stylesheet from jsDelivr, its icon from fastapi.tiangolo.com,
84	        # and starts from one inline script, allowed by its hash. The hash changes when FastAPI changes that script.
85	        location = /api/docs {
86	            proxy_pass http://api;
87	            proxy_set_header Host $host;
88	            proxy_set_header X-Request-ID $req_id;
89	            proxy_read_timeout 30s;
90	            add_header Content-Security-Policy "default-src 'self'; script-src 'self' https://cdn.jsdelivr.net 'sha256-eV3QMumkWxytVHa/LDvu+mnW+PcSAEI4SfFu0iIlbDc='; style-src 'self' https://cdn.jsdelivr.net; img-src 'self' data: https://fastapi.tiangolo.com; font-src 'self'; connect-src 'self'; object-src 'none'; base-uri 'self'; form-action 'self'; frame-ancestors 'none'" always;
91	            add_header X-Content-Type-Options nosniff always;
92	            add_header Referrer-Policy strict-origin-when-cross-origin always;
93	            add_header X-Frame-Options DENY always;
94	            add_header Permissions-Policy "camera=(), microphone=(), geolocation=()" always;
95	            add_header Cross-Origin-Opener-Policy same-origin always;
96	        }
97	
98	        # Vite puts a content hash in every asset's name, so a file never changes under its URL.
99	        # Cache-Control has no "always", so a missing asset's 404 is never cached for a year.
100	        location /assets/ {
101	            add_header Cache-Control "public, max-age=31536000, immutable";
102	            add_header Content-Security-Policy $csp always;
103	            add_header X-Content-Type-Options nosniff always;
104	            add_header Referrer-Policy strict-origin-when-cross-origin always;
