  const lists = sessions.map((session) => [
    "GET",
    `${API}/tasks`,
    null,
    params("teardown", { cookies: { session: { value: session || "", replace: true } } }),
  ]);
  const broken = inBatches(lists, SETUP_BATCH).filter((response) => response.status !== 200 || !isIntact(response.json("items")));
